import React from "react";
import {
  FaClone,
  FaUserCog,
  FaUserEdit,
  FaPhoneAlt,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaMicrochip,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaSyncAlt,
  FaFileAlt,
  FaCoins,
  FaBoxOpen,
  FaFileInvoice,
  FaExclamationCircle,
  FaChevronLeft,
  FaCommentDots,
} from "react-icons/fa";
import InfoField from "./InfoFieldComponenet";
import withRouter from "./withRouter";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class RequestDetailPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: null,
      clear: null,
      loading: true,
      authenticated: false,
    };

    this.handleBack = this.handleBack.bind(this);
    this.handleChat = this.handleChat.bind(this);
    this.handleAddRelated = this.handleAddRelated.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getRequestDetail();
      }
    );
  }

  getRequestDetail = () => {
    const { id } = this.props.params;
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/detail?id=${id}`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error("خطا در دریافت اطلاعات");
        }

        return response.json();
      })
      .then((data) => {
        console.log("REQUEST DETAIL:", data);

        this.setState({
          request: data.request || null,
          clear: data.clear || null,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET REQUEST DETAIL ERROR:", error);

        this.setState({
          request: null,
          clear: null,
          loading: false,
        });
      });
  };

  handleBack() {
    this.props.navigate(-1);
  }

  handleChat() {
    console.log("رفتن به گفتگو");
  }

  handleAddRelated() {
    console.log("افزودن درخواست مرتبط");
  }

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      request,
      clear,
      loading,
    } = this.state;

    if (loading) {
      return (
        <div className="text-center text-muted py-5">
          در حال دریافت اطلاعات...
        </div>
      );
    }

    if (!request) {
      return (
        <div className="text-center text-muted py-5">
          درخواست پیدا نشد.
        </div>
      );
    }

    /*
     * آیا درخواست تسویه دارد؟
     *
     * اگر clear وجود داشته باشد:
     * اطلاعات تسویه نمایش داده می‌شود.
     *
     * اگر clear وجود نداشته باشد:
     * هیچ‌کدام از فیلدهای مالی و تسویه نمایش داده نمی‌شوند.
     */
    const hasClear = clear !== null && clear !== undefined;

    /*
     * نام تعمیرکار
     */
    const technicianName = request.repairman_model
      ? `${request.repairman_model.name || ""} ${
          request.repairman_model.family || ""
        }`.trim()
      : "—";

    /*
     * وضعیت درخواست
     *
     * اگر clear وجود نداشته باشد:
     * منتظر تایید تعمیرکار
     *
     * اگر clear وجود داشته باشد:
     * وضعیت بر اساس cleared / status
     */
    let requestStatus = "منتظر تایید تعمیرکار";

    if (hasClear) {
      requestStatus = "تسویه شده";
    }

    /*
     * فیلدهای مربوط به clear
     */
    const totalReceived = Number(request.sum || 0);
    const suppliesCost = Number(request.abzar || 0);
    const totalFee = totalReceived - suppliesCost;
    const commissionPercent = Number(request.porsant || 0);

    const commissionAmount =
      totalFee > 0 && commissionPercent > 0
        ? (totalFee * commissionPercent) / 100
        : 0;

    /*
     * عکس فیش
     */
    const receiptImage =
      request.file1 && request.file1 !== ""
        ? `https://iranaserviceapp.ir/test/files/clear/${request.file1}`
        : null;

    /*
     * درخواست‌های مرتبط
     */
    const relatedRequests = Array.isArray(request.siblings)
      ? request.siblings
      : [];

    return (
      <div dir="rtl">
        <div className="container px-3 pt-4 pb-5">

          {/* هدر */}
          <div className="d-flex align-items-center justify-content-between mb-4">

            {/* بازگشت */}
            <button
              type="button"
              onClick={this.handleBack}
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaChevronLeft size={14} />
            </button>

            {/* گفتگو */}
            <button
              type="button"
              onClick={this.handleChat}
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center text-danger"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaCommentDots size={16} />
            </button>
          </div>

          {/* شماره درخواست */}
          <InfoField
            icon={<FaClone size={18} />}
            label="شماره درخواست"
            value={request.code || "—"}
          />

          {/* نام تعمیرکار */}
          <InfoField
            icon={<FaUserCog size={18} />}
            label="نام تعمیرکار"
            value={technicianName}
          />

          {/* نام مشتری */}
          <InfoField
            icon={<FaUserEdit size={18} />}
            label="نام مشتری"
            value={request.name || "—"}
          />

          {/* شماره تماس */}
          <InfoField
            icon={<FaPhoneAlt size={18} />}
            label="شماره تماس"
            value={request.mobile || "—"}
          />

          {/* تلفن ثابت */}
          <InfoField
            icon={<FaPhone size={18} />}
            label="تلفن ثابت"
            value={request.mobile2 || "—"}
          />

          {/* استان */}
          <InfoField
            icon={<FaMapMarkerAlt size={18} />}
            label="استان"
            value={request.state_model?.name || "—"}
          />

          {/* آدرس */}
          <InfoField
            icon={<FaImage size={18} />}
            label="آدرس"
            value={request.address || "—"}
          />

          {/* نوع دستگاه */}
          <InfoField
            icon={<FaMicrochip size={18} />}
            label="نوع دستگاه"
            value={request.device_type || "—"}
          />

          {/* برند دستگاه */}
          <InfoField
            icon={<FaTag size={18} />}
            label="برند دستگاه"
            value={request.device_brand || "—"}
          />

          {/* ایراد دستگاه */}
          <InfoField
            icon={<FaQuestionCircle size={18} />}
            label="ایراد دستگاه"
            value={request.problem || "—"}
          />

          {/* زمان مراجعه */}
          <InfoField
            icon={<FaClock size={18} />}
            label="زمان مراجعه"
            value={request.time || "—"}
          />

          {/* توضیحات */}
          <InfoField
            icon={<FaSyncAlt size={18} />}
            label="توضیحات"
            value={request.description || "—"}
          />

          {/* وضعیت */}
          <InfoField
            icon={<FaFileAlt size={18} />}
            label="وضعیت"
          >
            <span
              className={
                hasClear
                  ? "text-success fw-semibold"
                  : "text-warning fw-semibold"
              }
            >
              {requestStatus}
            </span>
          </InfoField>

          {/*
           * =====================================================
           * فقط زمانی که CLEAR وجود دارد این قسمت نمایش داده شود
           * =====================================================
           */}
          {hasClear && (
            <>
              {/* کل دریافتی */}
              <InfoField
                icon={<FaCoins size={18} />}
                label="کل دریافتی"
              >
                <span className="fw-semibold">
                  {totalReceived.toLocaleString("fa-IR")} تومان
                </span>
              </InfoField>

              {/* هزینه لوازم مصرفی */}
              <InfoField
                icon={<FaCoins size={18} />}
                label="هزینه لوازم مصرفی"
              >
                <span className="fw-semibold">
                  {suppliesCost.toLocaleString("fa-IR")} تومان
                </span>
              </InfoField>

              {/* لوازم مصرفی */}
              <InfoField
                icon={<FaBoxOpen size={18} />}
                label="لوازم مصرفی"
                value={request.abzar_details || "—"}
              />

              {/* کل اجرت */}
              <InfoField
                icon={<FaFileInvoice size={18} />}
                label="کل اجرت"
              >
                <span className="fw-semibold">
                  {totalFee.toLocaleString("fa-IR")} تومان
                </span>
              </InfoField>

              {/* پورسانت */}
              <InfoField
                icon={<FaFileInvoice size={18} />}
                label={`پورسانت (%${commissionPercent})`}
              >
                <span className="fw-semibold">
                  {commissionAmount.toLocaleString("fa-IR")} تومان
                </span>
              </InfoField>

              {/* فیش واریزی */}
              {receiptImage && (
                <div className="d-flex align-items-center justify-content-between gap-3 border rounded-4 px-3 py-3 mb-3 bg-white">

                  <span className="text-muted">
                    فیش واریزی:
                  </span>

                  <img
                    src={receiptImage}
                    alt="فیش واریزی"
                    className="rounded-3 border"
                    style={{
                      width: 140,
                      height: 110,
                      objectFit: "cover",
                      cursor: "pointer",
                    }}
                  />
                </div>
              )}

              {/* توضیحات تایید تسویه */}
              <InfoField
                icon={<FaExclamationCircle size={18} />}
                label="توضیحات تایید تسویه"
                value={clear.description || clear.desc || "—"}
              />
            </>
          )}

          {/* درخواست‌های مرتبط */}
          <h2 className="fs-6 fw-semibold text-dark mt-4 mb-3 text-end">
            درخواست‌های مرتبط:
          </h2>

          {relatedRequests.length === 0 ? (
            <div className="text-center text-muted py-4">
              هنوز موردی برای نمایش وجود ندارد.
            </div>
          ) : (
            <div>
              {relatedRequests.map((rel) => (
                <div
                  key={rel.id}
                  className="border rounded-3 p-3 mb-2 text-end"
                >
                  {rel.code || rel.id}
                </div>
              ))}
            </div>
          )}

          {/* افزودن درخواست مرتبط */}
          <button
            type="button"
            onClick={this.handleAddRelated}
            className="btn btn-primary w-100 rounded-3 py-3 mt-2"
          >
            افزودن درخواست مرتبط
          </button>
        </div>
      </div>
    );
  }
}

export default withRouter(RequestDetailPage);
